files.content:
:root {
  --bg: #1e1e2e;
  --card: #2a2a3c;
  --accent: #f9a826;
  --text: #e0e0e0;
  --muted: #8888aa;
  --border: #44445a;
  --shadow: #0f0f18;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
  image-rendering: pixelated;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 32px 28px;
  width: 100%;
  max-width: 400px;
  text-align: center;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.subtitle {
  margin: 0 0 24px;
  font-size: 0.95rem;
  color: var(--muted);
  letter-spacing: 0.5px;
}

.field {
  margin-bottom: 20px;
  text-align: left;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--muted);
}

input, select {
  width: 100%;
  padding: 12px 14px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input:hover, select:hover {
  border-color: var(--muted);
}

input:focus, select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(249, 168, 38, 0.35);
}

button {
  width: 100%;
  padding: 14px;
  font-size: 1.1rem;
  font-family: inherit;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--shadow);
  transition: transform 0.1s, box-shadow 0.1s, background 0.15s;
}

button:hover {
  background: #ffbe4d;
  border-color: #ffbe4d;
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--shadow);
}

.result-box {
  margin: 24px 0 20px;
  padding: 16px;
  background: var(--bg);
  border: 3px dashed var(--border);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.result-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

#result {
  font-size: 2rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
  min-height: 2.4rem;
  word-break: break-all;
}

.formulas {
  border-top: 3px solid var(--border);
  padding-top: 16px;
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.6;
  text-align: left;
}

.formulas p { margin: 0; }
.formulas strong { color: var(--text); }

@media (max-width: 360px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 1.3rem; }
  #result { font-size: 1.6rem; }
}

'use strict';

const input = document.getElementById('temperature');
const direction = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const resultEl = document.getElementById('result');

function convert() {
  const raw = input.value.trim();

  if (raw === '') {
    resultEl.textContent = 'Error';
    return;
  }

  const num = Number(raw);

  if (!Number.isFinite(num)) {
    resultEl.textContent = 'Error';
    return;
  }

  let output;
  if (direction.value === 'c-to-f') {
    output = num * 9 / 5 + 32;
  } else {
    output = (num - 32) * 5 / 9;
  }

  if (!Number.isFinite(output)) {
    resultEl.textContent = 'Error';
    return;
  }

  resultEl.textContent = output.toFixed(2);
}

convertBtn.addEventListener('click', convert);

input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    convert();
  }
});

direction.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    convert();
  }
});
